READ_SHAPES = {'searches': 'SELECT id,tags,`cursor`,complete,created,deleted_at,source_id,rating,page_offset,page_signature,collection_id FROM collection_sources', 'search_roots': 'SELECT query_key,folder_name FROM library_folders WHERE is_canonical=1', 'collection_folders': 'SELECT query_key,folder_name FROM library_folders', 'post_records': "SELECT p.*,p.tags_text AS tags,o.id AS media_id,o.url AS file_url,o.extension AS file_ext,o.width,o.height,o.file_size_bytes AS file_size,o.duration_ms,o.remote_md5 AS md5,o.checksum_algorithm,o.checksum,o.mime_type,v.url AS preview_url,s.url AS sample_url FROM posts p LEFT JOIN post_media o ON o.post_id=p.id AND o.media_role='original' AND o.position=0 LEFT JOIN post_media v ON v.post_id=p.id AND v.media_role='preview' AND v.position=0 LEFT JOIN post_media s ON s.post_id=p.id AND s.media_role='sample' AND s.position=0", 'matches': 'SELECT search_id,post_id,added_key FROM collection_posts', 'tag_terms': 'SELECT id,signature,name FROM tags', 'downloads': "SELECT m.post_id,CONCAT(TRIM(TRAILING '/' FROM r.configured_path),'/',l.relative_path) AS path,f.md5,l.downloaded_at AS completed FROM media_files mf JOIN post_media m ON m.id=mf.media_id JOIN files f ON f.id=mf.file_id JOIN file_locations l ON l.file_id=f.id JOIN storage_roots r ON r.id=l.storage_root_id WHERE l.status='present'", 'download_backoff': 'SELECT source_id,backoff_until AS `until`,consecutive_failures AS failures FROM source_runtime WHERE backoff_until IS NOT NULL', 'download_dispatch': 'SELECT source_id,last_download_started_at AS last_started FROM source_runtime'}
